.ac-barra-lateral{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-barra-lateral *{box-sizing:border-box}
.ac-barra-lateral h1,.ac-barra-lateral h2,.ac-barra-lateral h3,.ac-barra-lateral h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-barra-lateral a{color:inherit}
.ac-barra-lateral{padding:0.8rem;height:560px;background:#15161b}
.ac-barra-lateral-barra{width:230px;height:100%;border-radius:22px;border:1px solid rgba(255, 255, 255, 0.12);background:rgba(38, 39, 47,0.72);backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);box-shadow:0 12px 32px -12px rgba(0,0,0,0.45),inset 0 1px 0 rgba(255, 255, 255, 0.04);overflow:hidden;display:flex;flex-direction:column}
.ac-barra-lateral-marca{height:calc(84px - 0.8rem);flex-shrink:0;display:flex;align-items:center;padding:0 1.25rem;text-decoration:none}
.ac-barra-lateral-logo{font-family:'Anton',sans-serif;font-size:1.5rem;letter-spacing:0.04em;color:#ffffff}
.ac-barra-lateral-menu{position:relative;display:flex;flex-direction:column;gap:2px;padding:0.6rem 0.6rem 0;flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain}
.ac-barra-lateral-seccion{margin:0.4rem 0 0.25rem;padding:0 0.8rem;font-size:0.66rem;font-weight:600;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.5)}
.ac-barra-lateral-seccion--sistema{margin-top:1rem}
.ac-barra-lateral-pastilla{position:absolute;left:0.6rem;right:0.6rem;top:0;height:0;border-radius:999px;opacity:0;pointer-events:none;transition:transform 0.3s cubic-bezier(0.3,0.7,0.2,1),height 0.3s cubic-bezier(0.3,0.7,0.2,1),opacity 0.2s ease}
.ac-barra-lateral-activo-p{background:rgba(224, 43, 32, 0.12);box-shadow:inset 0 0 0 1px rgba(224,43,32,0.25)}
.ac-barra-lateral-hover-p{background:rgba(255, 255, 255, 0.08)}
.ac-barra-lateral-pastilla.ac-barra-lateral-visible{opacity:1}
.ac-barra-lateral-enlace{position:relative;z-index:1;display:flex;align-items:center;gap:0.6rem;padding:0.6rem 0.8rem;border-radius:999px;color:rgba(255, 255, 255, 0.62);text-decoration:none;font-weight:500;font-size:0.8rem;white-space:nowrap;transition:color 0.15s ease}
.ac-barra-lateral-enlace svg{width:17px;height:17px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;transition:color 0.15s ease}
.ac-barra-lateral-txt{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis}
.ac-barra-lateral-enlace:hover{color:#ffffff}
.ac-barra-lateral-enlace:hover svg,.ac-barra-lateral-enlace.ac-barra-lateral-es-activo svg{color:#ff3b30}
.ac-barra-lateral-enlace.ac-barra-lateral-es-activo{color:#ffffff}
.ac-barra-lateral-perfil{flex-shrink:0;margin:auto 0.8rem 0;padding:0.8rem 0;border-top:1px solid rgba(255, 255, 255, 0.12);display:flex;flex-direction:column;gap:0.6rem}
.ac-barra-lateral-ident{display:flex;align-items:center;gap:0.6rem;text-decoration:none}
.ac-barra-lateral-avatar{width:34px;height:34px;flex-shrink:0;display:flex;align-items:center;justify-content:center;border-radius:999px;background:rgba(224, 43, 32, 0.16);color:#ff6659;font-weight:700;font-size:0.8rem}
.ac-barra-lateral-datos{display:flex;flex-direction:column;gap:0.25rem;min-width:0}
.ac-barra-lateral-nombre{font-size:0.9rem;color:#ffffff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ac-barra-lateral-insignia{align-self:flex-start;display:inline-flex;padding:0.25rem 0.6rem;border-radius:999px;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;line-height:1;background:rgba(224, 43, 32, 0.16);color:#ff6659}
.ac-barra-lateral-acciones{display:flex;gap:0.6rem}
.ac-barra-lateral-salir{flex:1;display:inline-flex;align-items:center;justify-content:center;font-size:0.8rem;color:rgba(255, 255, 255, 0.62);text-decoration:none;padding:0.4rem 0.8rem;border:1px solid rgba(255, 255, 255, 0.16);border-radius:9px;transition:color 0.15s ease,border-color 0.15s ease}
.ac-barra-lateral-salir:hover{color:#ffffff;border-color:#e02b20}
.ac-barra-lateral-tema{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;flex-shrink:0;border-radius:999px;border:1px solid rgba(255, 255, 255, 0.16);background:transparent;color:rgba(255, 255, 255, 0.62);cursor:pointer;transition:background 0.2s cubic-bezier(0.25, 0.1, 0.25, 1),color 0.2s cubic-bezier(0.25, 0.1, 0.25, 1),border-color 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)}
.ac-barra-lateral-tema:hover{background:rgba(255, 255, 255, 0.04);color:#ffffff;border-color:#e02b20}
.ac-barra-lateral-tema svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}

.ac-menu-movil{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-menu-movil *{box-sizing:border-box}
.ac-menu-movil h1,.ac-menu-movil h2,.ac-menu-movil h3,.ac-menu-movil h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-menu-movil a{color:inherit}
.ac-menu-movil{position:relative;width:360px;max-width:100%;height:520px;overflow:hidden;padding:0}
.ac-menu-movil-barra{margin:0.6rem 0.6rem 0;display:flex;align-items:center;padding:0.6rem 0.6rem 0.6rem 1rem;border-radius:20px;border:1px solid rgba(255, 255, 255, 0.12);background:rgba(38, 39, 47,0.72);backdrop-filter:blur(16px)}
.ac-menu-movil-logo{font-family:'Anton',sans-serif;font-size:1.2rem;letter-spacing:0.04em}
.ac-menu-movil-hamb{margin-left:auto;display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:9px;border:1px solid rgba(255, 255, 255, 0.16);background:transparent;color:rgba(255, 255, 255, 0.62);cursor:pointer;touch-action:manipulation;transition:transform 0.1s ease-out}
.ac-menu-movil-hamb:active{transform:scale(0.92)}
.ac-menu-movil-hamb svg,.ac-menu-movil-cerrar svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round}
.ac-menu-movil-pagina{padding:1rem 1.25rem}
.ac-menu-movil-miga{margin:0 0 0.25rem;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.5)}
.ac-menu-movil-h1{margin:0;font-size:1.6rem}
.ac-menu-movil-fondo{position:absolute;inset:0;background:rgba(0,0,0,0.5);opacity:0;pointer-events:none;transition:opacity 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)}
.ac-menu-movil.ac-menu-movil-abierto .ac-menu-movil-fondo{opacity:1;pointer-events:auto}
.ac-menu-movil-panel{position:absolute;top:0.6rem;right:0.6rem;bottom:0.6rem;width:min(82%,300px);border-radius:22px;border:1px solid rgba(255, 255, 255, 0.12);background:rgba(38, 39, 47,0.92);backdrop-filter:blur(18px) saturate(140%);box-shadow:0 24px 60px -20px rgba(0,0,0,0.6);padding:1rem 0.8rem;display:flex;flex-direction:column;gap:2px;overflow-y:auto;transform:translateX(calc(100% + 1rem));transition:transform 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)}
.ac-menu-movil.ac-menu-movil-abierto .ac-menu-movil-panel{transform:translateX(0)}
.ac-menu-movil-cerrar{align-self:flex-end;display:grid;place-items:center;width:36px;height:36px;margin-bottom:0.4rem;border-radius:999px;border:1px solid rgba(255, 255, 255, 0.16);background:transparent;color:rgba(255, 255, 255, 0.62);cursor:pointer}
.ac-menu-movil-cerrar svg{width:18px;height:18px}
.ac-menu-movil-sec{margin:0 0 0.6rem;padding:0 1rem;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.5)}
.ac-menu-movil-enl{display:flex;align-items:center;gap:0.6rem;padding:0.6rem 0.8rem;border-radius:999px;color:rgba(255, 255, 255, 0.62);text-decoration:none;font-weight:500;font-size:0.8rem}
.ac-menu-movil-enl svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.ac-menu-movil-enl:hover{background:rgba(255, 255, 255, 0.08);color:#ffffff}
.ac-menu-movil-enl:hover svg,.ac-menu-movil-enl.ac-menu-movil-activo svg{color:#ff3b30}
.ac-menu-movil-enl.ac-menu-movil-activo{background:rgba(224, 43, 32, 0.12);box-shadow:inset 0 0 0 1px rgba(224,43,32,0.25);color:#ffffff}
.ac-menu-movil-sep{height:1px;background:rgba(255, 255, 255, 0.12);margin:0.8rem 0}
.ac-menu-movil-salir{text-align:center;font-size:0.8rem;color:rgba(255, 255, 255, 0.62);text-decoration:none;padding:0.6rem 0.8rem;border:1px solid rgba(255, 255, 255, 0.16);border-radius:9px}

.ac-cabecera-seccion{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-cabecera-seccion *{box-sizing:border-box}
.ac-cabecera-seccion h1,.ac-cabecera-seccion h2,.ac-cabecera-seccion h3,.ac-cabecera-seccion h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-cabecera-seccion a{color:inherit}
.ac-cabecera-seccion{display:flex;flex-direction:column;gap:1.5rem;padding:0 0 1.5rem}
.ac-cabecera-seccion-topbar{height:84px;display:flex;flex-direction:column;justify-content:center;padding:0 2rem;border-bottom:1px solid rgba(255, 255, 255, 0.12)}
.ac-cabecera-seccion-miga{margin:0 0 0.25rem;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.5)}
.ac-cabecera-seccion-miga a{color:rgba(255, 255, 255, 0.5);text-decoration:none}
.ac-cabecera-seccion-miga a:hover{color:rgba(255, 255, 255, 0.62);text-decoration:underline}
.ac-cabecera-seccion-h1{margin:0;font-size:1.6rem}
.ac-cabecera-seccion-cab{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem;padding:0 2rem}
.ac-cabecera-seccion-resumen{display:flex;align-items:center;flex:1 1 240px;min-width:0;gap:0.8rem;margin:0;color:rgba(255, 255, 255, 0.62);font-size:0.9rem}
.ac-cabecera-seccion-icono{display:grid;place-items:center;width:34px;height:34px;flex-shrink:0;border-radius:9px;background:rgba(224, 43, 32, 0.12);color:#ff3b30}
.ac-cabecera-seccion-icono svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.ac-cabecera-seccion-boton{display:inline-flex;align-items:center;justify-content:center;font-family:inherit;font-weight:600;font-size:0.9rem;padding:0.6rem 1.25rem;border-radius:999px;border:1px solid transparent;cursor:pointer;white-space:nowrap;background:linear-gradient(#ff3b30,#e02b20);color:#fff;box-shadow:0 1px 2px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.12);transition:background 0.2s cubic-bezier(0.25, 0.1, 0.25, 1),box-shadow 0.2s cubic-bezier(0.25, 0.1, 0.25, 1),transform 0.1s ease-out}
.ac-cabecera-seccion-boton:hover{background:linear-gradient(#ff3b30,#ff3b30);box-shadow:0 2px 6px rgba(224, 43, 32, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.12)}
.ac-cabecera-seccion-boton:active{transform:scale(0.96)}
.ac-cabecera-seccion-alta{margin:0 2rem;background:#1b1c22;border:1px solid rgba(255, 255, 255, 0.12);border-radius:16px;padding:1.5rem;box-shadow:0 1px 2px rgba(0, 0, 0, 0.2), 0 8px 24px rgba(0, 0, 0, 0.25)}
.ac-cabecera-seccion-alta[hidden]{display:none}
.ac-cabecera-seccion-eyebrow{margin:0 0 0.4rem;font-size:0.72rem;font-weight:700;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.62)}
.ac-cabecera-seccion-titulo{margin:0 0 1.25rem;font-size:1.3rem}
.ac-cabecera-seccion-nota{margin:0;color:rgba(255, 255, 255, 0.5);font-size:0.8rem}

.ac-selector-segmentado{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-selector-segmentado *{box-sizing:border-box}
.ac-selector-segmentado h1,.ac-selector-segmentado h2,.ac-selector-segmentado h3,.ac-selector-segmentado h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-selector-segmentado a{color:inherit}
.ac-selector-segmentado-seg{position:relative;display:inline-flex;flex-wrap:wrap;align-items:stretch;gap:2px;max-width:100%;padding:4px;border-radius:22px;border:1px solid rgba(255, 255, 255, 0.12);background:#15161b}
.ac-selector-segmentado-pastilla{position:absolute;top:0;left:0;width:0;border-radius:18px;background:linear-gradient(135deg,#ff3b30,#e02b20);box-shadow:0 4px 14px -6px rgba(224,43,32,0.7);opacity:0;pointer-events:none;transition:transform 0.3s cubic-bezier(0.3,0.7,0.2,1),width 0.3s cubic-bezier(0.3,0.7,0.2,1),height 0.3s cubic-bezier(0.3,0.7,0.2,1)}
.ac-selector-segmentado-seg.ac-selector-segmentado-con-pastilla .ac-selector-segmentado-pastilla{opacity:1}
.ac-selector-segmentado-seg>button,.ac-selector-segmentado-seg>a{position:relative;z-index:1;display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;padding:0.6rem 1rem;border:none;border-radius:18px;background:transparent;color:rgba(255, 255, 255, 0.62);font-family:inherit;font-size:0.72rem;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;text-decoration:none;white-space:nowrap;cursor:pointer;transition:color 0.25s ease}
.ac-selector-segmentado-seg>:is(button,a):hover{color:#ffffff}
.ac-selector-segmentado-seg>:is(button,a):is([aria-selected="true"],[aria-pressed="true"]){color:#fff}
.ac-selector-segmentado-seg:not(.ac-selector-segmentado-con-pastilla)>:is([aria-selected="true"],[aria-pressed="true"]){background:linear-gradient(135deg,#ff3b30,#e02b20)}
.ac-selector-segmentado-seg>:is(button,a):focus-visible{outline:none;box-shadow:0 0 0 3px rgba(224, 43, 32, 0.35)}
.ac-selector-segmentado-nota{font-size:0.68rem;font-weight:500;letter-spacing:0;text-transform:none;opacity:0.75}
@media (max-width:560px){.ac-selector-segmentado-seg{display:flex;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}.ac-selector-segmentado-seg::-webkit-scrollbar{display:none}.ac-selector-segmentado-seg>:is(button,a){flex:none;padding:0.6rem 0.8rem}}

piezas.js:
(function(){document.querySelectorAll('.ac-selector-segmentado-seg').forEach(function(g){
  var p=g.querySelector('.ac-selector-segmentado-pastilla');
  var items=[].slice.call(g.querySelectorAll(':scope>button,:scope>a'));
  function attr(el){return el.hasAttribute('aria-pressed')?'aria-pressed':'aria-selected';}
  function colocar(){var el=items.find(function(i){return i.getAttribute(attr(i))==='true';});if(!el)return;
    p.style.width=el.offsetWidth+'px';p.style.height=el.offsetHeight+'px';p.style.transform='translate('+el.offsetLeft+'px,'+el.offsetTop+'px)';g.classList.add('ac-selector-segmentado-con-pastilla');}
  items.forEach(function(i){i.addEventListener('click',function(e){e.preventDefault();items.forEach(function(x){x.setAttribute(attr(x),'false');});i.setAttribute(attr(i),'true');colocar();});});
  colocar();window.addEventListener('resize',colocar);
});})();

piezas.css:
.ac-pestanas-partes{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-pestanas-partes *{box-sizing:border-box}
.ac-pestanas-partes h1,.ac-pestanas-partes h2,.ac-pestanas-partes h3,.ac-pestanas-partes h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-pestanas-partes a{color:inherit}
.ac-pestanas-partes-envoltorio{container-type:inline-size}
.ac-pestanas-partes-tabs{display:none;gap:2px;padding:4px;border-radius:22px;border:1px solid rgba(255, 255, 255, 0.12);background:#15161b;margin-bottom:1rem}
.ac-pestanas-partes-tabs>button{flex:1 1 auto;padding:0.6rem 1rem;border:none;border-radius:18px;background:transparent;color:rgba(255, 255, 255, 0.62);font-family:inherit;font-size:0.72rem;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;cursor:pointer;line-height:1.25;white-space:normal}
.ac-pestanas-partes-tabs>button[aria-selected="true"]{background:linear-gradient(135deg,#ff3b30,#e02b20);color:#fff}
.ac-pestanas-partes-columnas{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}
.ac-pestanas-partes-parte{padding:1rem;border-radius:18px;border:1px solid rgba(255, 255, 255, 0.12);background:#26272f;box-shadow:0 1px 2px rgba(0, 0, 0, 0.2), 0 8px 24px rgba(0, 0, 0, 0.25)}
.ac-pestanas-partes-parte p{margin:0.4rem 0 0;color:rgba(255, 255, 255, 0.62);font-size:0.8rem}
@container (max-width:899px){.ac-pestanas-partes-tabs{display:flex;flex-wrap:wrap}.ac-pestanas-partes-columnas{grid-template-columns:1fr}.ac-pestanas-partes-parte[data-oculta]{display:none}}
@container (max-width:560px){.ac-pestanas-partes-tabs:has(>button:nth-of-type(4)){display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}}

.ac-tabla-listado{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-tabla-listado *{box-sizing:border-box}
.ac-tabla-listado h1,.ac-tabla-listado h2,.ac-tabla-listado h3,.ac-tabla-listado h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-tabla-listado a{color:inherit}
.ac-tabla-listado-envoltorio{overflow-x:auto;border:1px solid rgba(255, 255, 255, 0.12);border-radius:16px;background:#26272f;box-shadow:0 1px 2px rgba(0, 0, 0, 0.2), 0 8px 24px rgba(0, 0, 0, 0.25)}
.ac-tabla-listado-tabla{width:100%;min-width:560px;border-collapse:separate;border-spacing:0;font-size:0.8rem}
.ac-tabla-listado-tabla th{text-align:left;vertical-align:middle;padding:0.6rem 1rem;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.08em;color:rgba(255, 255, 255, 0.62);background:#1b1c22;border-bottom:1px solid rgba(255, 255, 255, 0.16);white-space:nowrap}
.ac-tabla-listado-tabla td{vertical-align:middle;padding:0.8rem 1rem;border-bottom:1px solid rgba(255, 255, 255, 0.12);white-space:nowrap}
.ac-tabla-listado-tabla th+th,.ac-tabla-listado-tabla td+td{border-left:1px solid rgba(255, 255, 255, 0.12)}
.ac-tabla-listado-tabla tbody tr:last-child td{border-bottom:none}
.ac-tabla-listado-tabla tbody tr:nth-child(even){background:rgba(255,255,255,0.03)}
.ac-tabla-listado-tabla tbody tr:hover{background:rgba(255, 255, 255, 0.04)}
.ac-tabla-listado-check{width:1%}
.ac-tabla-listado-tenue{color:rgba(255, 255, 255, 0.62)}
.ac-tabla-listado-enlace{color:#ffffff;text-decoration:none;font-weight:500;margin-right:0.4rem}
.ac-tabla-listado-enlace:hover{color:#ff3b30}
.ac-tabla-listado-ins{display:inline-flex;align-items:center;padding:0.25rem 0.6rem;border-radius:999px;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;line-height:1}
.ac-tabla-listado-gris{background:rgba(255, 255, 255, 0.08);color:rgba(255, 255, 255, 0.62)}
.ac-tabla-listado-verde{background:rgba(18, 214, 120, 0.16);color:#12d678}
.ac-tabla-listado-azul{background:rgba(91, 157, 255, 0.16);color:#5b9dff}
