(function(){document.querySelectorAll('.ac-editor-texto').forEach(function(r){
  var a=r.querySelector('.ac-editor-texto-area'),v=r.querySelector('.ac-editor-texto-valor');function sync(){v.value=a.innerHTML;}
  r.querySelectorAll('[data-cmd]').forEach(function(b){b.addEventListener('mousedown',function(e){e.preventDefault();var c=b.getAttribute('data-cmd');
    if(c==='createLink'){var u=prompt('Dirección del enlace');if(u)document.execCommand(c,false,u);}else document.execCommand(c,false,null);sync();});});
  a.addEventListener('input',sync);sync();
});})();

