.ac-arbol-casillas input[type=checkbox]::before,.ac-arbol-casillas input[type=radio]::before{content:"";transform:scale(0);transition:transform 0.12s ease-out;background:#ff3b30}
.ac-arbol-casillas input[type=radio]::before{width:9px;height:9px;border-radius:50%}
.ac-arbol-casillas input[type=checkbox]::before{width:11px;height:11px;clip-path:polygon(13% 45%,0 63%,40% 100%,100% 20%,82% 5%,40% 72%)}
.ac-arbol-casillas input[type=checkbox]:checked::before,.ac-arbol-casillas input[type=radio]:checked::before{transform:scale(1)}
.ac-arbol-casillas input[type=checkbox]:checked,.ac-arbol-casillas input[type=radio]:checked{border-color:#ff3b30}
.ac-arbol-casillas .ac-arbol-casillas-check{flex-direction:row;align-items:center;gap:0.6rem;cursor:pointer}

.ac-arbol-casillas-lista{display:flex;flex-direction:column;gap:0.8rem;max-width:560px}
.ac-arbol-casillas-grupo{min-width:0;background:#1b1c22;border:1px solid rgba(255, 255, 255, 0.12);border-radius:16px;padding:0.8rem 1rem}
.ac-arbol-casillas-gt{display:flex;align-items:center;gap:0.4rem;margin:calc(0.8rem * -1) calc(1rem * -1);padding:0.8rem 1rem;font-size:0.8rem;font-weight:600;text-transform:uppercase;letter-spacing:0.05em;cursor:pointer;list-style:none;border-radius:16px}
.ac-arbol-casillas-gt:hover{background:rgba(255, 255, 255, 0.04)}
.ac-arbol-casillas-gt::-webkit-details-marker,.ac-arbol-casillas-bt::-webkit-details-marker{display:none}
.ac-arbol-casillas-gt::before{content:"▸";flex-shrink:0;font-size:0.85em;color:#ff3b30;transition:transform 0.15s ease}
.ac-arbol-casillas-grupo[open]>.ac-arbol-casillas-gt::before{transform:rotate(90deg)}
.ac-arbol-casillas-gt input{margin-right:0.4rem}
.ac-arbol-casillas-n{color:rgba(255, 255, 255, 0.5);font-weight:500;text-transform:none;letter-spacing:normal}
.ac-arbol-casillas-cuerpo{padding-top:1rem}
.ac-arbol-casillas-bloque+.ac-arbol-casillas-bloque{margin-top:0.6rem}
.ac-arbol-casillas-bloque{border-left:2px solid rgba(255, 255, 255, 0.16);padding-left:0.8rem}
.ac-arbol-casillas-bt{display:inline-flex;align-items:center;gap:0.4rem;padding:0.25rem 0;font-weight:500;cursor:pointer;list-style:none}
.ac-arbol-casillas-bt::before{content:"▸";font-size:0.85em;color:rgba(255, 255, 255, 0.5);transition:transform 0.15s ease}
.ac-arbol-casillas-bloque[open]>.ac-arbol-casillas-bt::before{transform:rotate(90deg)}
.ac-arbol-casillas .ac-arbol-casillas-fila{display:flex;flex-direction:row;align-items:center;gap:0.8rem;padding:0.6rem 1rem;border-bottom:1px solid rgba(255, 255, 255, 0.12);color:#ffffff;font-size:0.9rem;cursor:pointer}
.ac-arbol-casillas .ac-arbol-casillas-fila:last-child{border-bottom:none}
